import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv2d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void conv2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C_in, int H_in, int W_in,
    int C_out, int K, int stride, int pad,
    int H_out, int W_out)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * C_out * H_out * W_out;
    if (idx >= total) return;

    int w_out = idx % W_out;
    int h_out = (idx / W_out) % H_out;
    int c_out = (idx / (W_out * H_out)) % C_out;
    int n = idx / (W_out * H_out * C_out);

    float sum = bias[c_out];

    int h_in_start = h_out * stride - pad;
    int w_in_start = w_out * stride - pad;

    for (int c_in = 0; c_in < C_in; ++c_in) {
        const float* input_ptr = input + ((n * C_in + c_in) * H_in) * W_in;
        const float* weight_ptr = weight + ((c_out * C_in + c_in) * K) * K;

        #pragma unroll
        for (int kh = 0; kh < K; ++kh) {
            int h_in = h_in_start + kh;
            if (h_in < 0 || h_in >= H_in) continue;
            const float* input_row = input_ptr + h_in * W_in;
            const float* weight_row = weight_ptr + kh * K;
            #pragma unroll
            for (int kw = 0; kw < K; ++kw) {
                int w_in = w_in_start + kw;
                if (w_in < 0 || w_in >= W_in) continue;
                sum += input_row[w_in] * weight_row[kw];
            }
        }
    }

    output[idx] = sum;
}

torch::Tensor conv2d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int pad)
{
    input = input.contiguous();
    weight = weight.contiguous();
    bias = bias.contiguous();

    int N = input.size(0);
    int C_in = input.size(1);
    int H_in = input.size(2);
    int W_in = input.size(3);

    int C_out = weight.size(0);
    int K = weight.size(2);

    int H_out = (H_in + 2 * pad - K) / stride + 1;
    int W_out = (W_in + 2 * pad - K) / stride + 1;

    auto output = torch::empty({N, C_out, H_out, W_out}, input.options());

    int total = N * C_out * H_out * W_out;
    int threads = 256;
    int blocks = (total + threads - 1) / threads;

    conv2d_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C_in, H_in, W_in,
        C_out, K, stride, pad,
        H_out, W_out
    );

    return output;
}
"""

conv2d_header = r"""
#include <torch/extension.h>
torch::Tensor conv2d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int pad);
"""

conv2d_module = load_inline(
    name="conv2d_module",
    cpp_sources=conv2d_header,
    cuda_sources=conv2d_source,
    functions=["conv2d_forward"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        self.weight = nn.Parameter(torch.empty(96, 3, 11, 11))
        self.bias = nn.Parameter(torch.empty(96))
        nn.init.kaiming_uniform_(self.weight, a=5 ** 0.5)
        fan_in = 3 * 11 * 11
        bound = 1 / (fan_in ** 0.5)
        nn.init.uniform_(self.bias, -bound, bound)
        self.stride = 4
        self.padding = 2

    def forward(self, x):
        x = x.cuda().contiguous()
        return conv2d_module.conv2d_forward(x, self.weight, self.bias, self.stride, self.padding)


batch_size = 256
num_classes = 1000


def get_inputs():
    return [torch.rand(batch_size, 3, 224, 224)]


def get_init_inputs():
    return [num_classes]

